import { onMounted, onUnmounted, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useAuthStore } from '@/stores/auth'
import { useRealtimeStore, type RealtimeEvent, type RealtimeTopic } from '@/stores/realtime'

export function useRealtime(topics: RealtimeTopic[] = ['alerts', 'incidents', 'nodes']) {
  const authStore = useAuthStore()
  const realtimeStore = useRealtimeStore()
  const { connected, events, latestAlert, latestIncident, latestNodeEvent, latestHealEvent } = storeToRefs(realtimeStore)

  let unwatchAuth: (() => void) | null = null

  onMounted(() => {
    if (authStore.isLoggedIn) {
      realtimeStore.connect()
      realtimeStore.subscribe(topics)
    }

    unwatchAuth = watch(
      () => authStore.isLoggedIn,
      (loggedIn) => {
        if (loggedIn) {
          realtimeStore.connect()
          realtimeStore.subscribe(topics)
        } else {
          realtimeStore.disconnect()
        }
      }
    )
  })

  onUnmounted(() => {
    if (unwatchAuth) {
      unwatchAuth()
    }
    // 页面卸载时断开 WebSocket（全局 store 会在重新登录后重建）
    realtimeStore.disconnect()
  })

  return {
    connected,
    events,
    latestAlert,
    latestIncident,
    latestNodeEvent,
    latestHealEvent,
    connect: () => realtimeStore.connect(),
    disconnect: () => realtimeStore.disconnect(),
    subscribe: (t: RealtimeTopic[]) => realtimeStore.subscribe(t),
    unsubscribe: (t: RealtimeTopic[]) => realtimeStore.unsubscribe(t),
  }
}

export type { RealtimeEvent, RealtimeTopic }
