import { defineStore } from 'pinia'
import { computed, ref } from 'vue'
import { getWsBaseUrl } from '@/api/client'
import { useAuthStore } from '@/stores/auth'

export type RealtimeTopic = 'alerts' | 'incidents' | 'nodes' | 'heal' | 'notifications'

export interface RealtimeEvent {
  event_type: string
  timestamp: string
  payload: Record<string, unknown>
}

const DEFAULT_TOPICS: RealtimeTopic[] = ['alerts', 'incidents', 'nodes']
const HEARTBEAT_INTERVAL_MS = 30000
const MAX_RECONNECT_DELAY_MS = 30000

export const useRealtimeStore = defineStore('realtime', () => {
  const ws = ref<WebSocket | null>(null)
  const connected = ref(false)
  const connecting = ref(false)
  const events = ref<RealtimeEvent[]>([])
  const subscribedTopics = ref<Set<RealtimeTopic>>(new Set())
  const lastEventTime = ref<Date | null>(null)

  let reconnectTimer: ReturnType<typeof setTimeout> | null = null
  let heartbeatTimer: ReturnType<typeof setInterval> | null = null
  let reconnectAttempt = 0
  let intentionalClose = false

  const latestAlert = computed<RealtimeEvent | null>(() => {
    return events.value.find((e) => e.event_type.startsWith('alert.')) || null
  })

  const latestIncident = computed<RealtimeEvent | null>(() => {
    return events.value.find((e) => e.event_type.startsWith('incident.')) || null
  })

  const latestNodeEvent = computed<RealtimeEvent | null>(() => {
    return events.value.find((e) => e.event_type.startsWith('node.')) || null
  })

  const latestHealEvent = computed<RealtimeEvent | null>(() => {
    return events.value.find((e) => e.event_type.startsWith('heal.')) || null
  })

  function buildUrl(): string {
    const base = getWsBaseUrl()
    const host = base.replace(/:$/, '') // 移除末尾冒号
    return `${host}/ws/v1/dashboard`
  }

  function connect() {
    const authStore = useAuthStore()
    if (!authStore.isLoggedIn || connecting.value || connected.value) {
      return
    }

    intentionalClose = false
    connecting.value = true

    try {
      const url = buildUrl()
      const socket = new WebSocket(url)
      ws.value = socket

      socket.onopen = () => {
        connected.value = true
        connecting.value = false
        reconnectAttempt = 0
        // 后端通过 httpOnly cookie 鉴权，这里只发送 auth 动作，不再暴露 token
        send({ action: 'auth' })
        subscribe(DEFAULT_TOPICS)
        sendSyncSince()
        startHeartbeat()
      }

      socket.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data) as RealtimeEvent | { action: string }
          if ('event_type' in data) {
            events.value.unshift(data)
            // 限制事件缓存数量
            if (events.value.length > 200) {
              events.value = events.value.slice(0, 200)
            }
            lastEventTime.value = new Date()
          }
        } catch {
          // 忽略无法解析的消息
        }
      }

      socket.onclose = () => {
        cleanupSocket()
        if (!intentionalClose) {
          scheduleReconnect()
        }
      }

      socket.onerror = () => {
        // 错误时让 onclose 处理重连
      }
    } catch {
      connecting.value = false
      scheduleReconnect()
    }
  }

  function disconnect() {
    intentionalClose = true
    if (reconnectTimer) {
      clearTimeout(reconnectTimer)
      reconnectTimer = null
    }
    stopHeartbeat()
    if (ws.value) {
      try {
        ws.value.close()
      } catch {
        // ignore
      }
      ws.value = null
    }
    connected.value = false
    connecting.value = false
  }

  function cleanupSocket() {
    connected.value = false
    connecting.value = false
    stopHeartbeat()
    if (ws.value) {
      ws.value = null
    }
  }

  function scheduleReconnect() {
    if (reconnectTimer || intentionalClose) {
      return
    }
    const delay = Math.min(1000 * 2 ** reconnectAttempt, MAX_RECONNECT_DELAY_MS)
    reconnectAttempt += 1
    reconnectTimer = setTimeout(() => {
      reconnectTimer = null
      connect()
    }, delay)
  }

  function startHeartbeat() {
    stopHeartbeat()
    heartbeatTimer = setInterval(() => {
      send({ action: 'ping' })
    }, HEARTBEAT_INTERVAL_MS)
  }

  function stopHeartbeat() {
    if (heartbeatTimer) {
      clearInterval(heartbeatTimer)
      heartbeatTimer = null
    }
  }

  function send(message: Record<string, unknown>) {
    if (ws.value?.readyState === WebSocket.OPEN) {
      try {
        ws.value.send(JSON.stringify(message))
      } catch {
        // ignore
      }
    }
  }

  function subscribe(topics: RealtimeTopic[]) {
    topics.forEach((t) => subscribedTopics.value.add(t))
    send({ action: 'subscribe', topics })
  }

  function unsubscribe(topics: RealtimeTopic[]) {
    topics.forEach((t) => subscribedTopics.value.delete(t))
    send({ action: 'unsubscribe', topics })
  }

  function sendSyncSince() {
    const since = lastEventTime.value
      ? lastEventTime.value.toISOString()
      : new Date(Date.now() - 5 * 60 * 1000).toISOString()
    send({ action: 'sync_since', since })
  }

  function clearEvents() {
    events.value = []
  }

  return {
    ws,
    connected,
    connecting,
    events,
    subscribedTopics,
    lastEventTime,
    latestAlert,
    latestIncident,
    latestNodeEvent,
    latestHealEvent,
    connect,
    disconnect,
    subscribe,
    unsubscribe,
    sendSyncSince,
    clearEvents,
  }
})
